/**
 * Database Restore Script (Native PostgreSQL, no psql or Docker required)
 *
 * Restores tables from a JSON backup file generated by backupDatabase.ts.
 * Connects directly to the PostgreSQL database (Railway) via pg Pool.
 *
 * Usage:
 *   npx tsx src/scripts/db/restoreDatabase.ts --dev [--file path/to/backup.json] [--confirm]
 *   npx tsx src/scripts/db/restoreDatabase.ts --prod [--file path/to/backup.json] [--confirm]
 */

import fs from 'fs';
import path from 'path';
import { getDbPool } from '../../db/drizzle.js';
import { initScriptEnv } from '../scriptEnv.js';

const scriptEnv = initScriptEnv();
const isProd = scriptEnv.isProd;
const isConfirmed = process.argv.includes('--confirm');

/**
 * Dynamically computes topological dependency order of tables by inspecting foreign key metadata
 * from information_schema.
 */
async function computeTopologicalOrder(
  pool: ReturnType<typeof getDbPool>,
  targetTables: string[]
): Promise<string[]> {
  const targetSet = new Set(targetTables);
  const dependencies = new Map<string, Set<string>>();
  for (const t of targetTables) {
    dependencies.set(t, new Set());
  }

  try {
    const res = await pool.query<{ table_name: string; foreign_table_name: string }>(`
      SELECT
        tc.table_name, 
        ccu.table_name AS foreign_table_name
      FROM 
        information_schema.table_constraints AS tc 
        JOIN information_schema.constraint_column_usage AS ccu
          ON ccu.constraint_name = tc.constraint_name
          AND ccu.table_schema = tc.table_schema
      WHERE tc.constraint_type = 'FOREIGN KEY' 
        AND tc.table_schema = 'public'
    `);

    for (const row of res.rows) {
      if (
        row.table_name !== row.foreign_table_name &&
        targetSet.has(row.table_name) &&
        targetSet.has(row.foreign_table_name)
      ) {
        dependencies.get(row.table_name)?.add(row.foreign_table_name);
      }
    }
  } catch (err) {
    console.warn('⚠️ Could not query foreign key dependencies for topological sort:', err);
    return targetTables;
  }

  // Topological sort (DFS with cycle prevention)
  const sorted: string[] = [];
  const visited = new Set<string>();

  function visit(node: string, currentPath = new Set<string>()) {
    if (visited.has(node)) return;
    if (currentPath.has(node)) return; // Cycle broken
    currentPath.add(node);
    for (const dep of dependencies.get(node) || []) {
      visit(dep, currentPath);
    }
    currentPath.delete(node);
    visited.add(node);
    sorted.push(node);
  }

  for (const t of targetTables) {
    visit(t);
  }

  return sorted;
}

function getSpecifiedOrLatestBackup(): string | null {
  const fileArgIndex = process.argv.indexOf('--file');
  if (fileArgIndex !== -1 && process.argv[fileArgIndex + 1]) {
    const specified = path.resolve(process.cwd(), process.argv[fileArgIndex + 1]);
    if (fs.existsSync(specified)) return specified;
    console.error(`❌ Specified backup file not found: ${specified}`);
    process.exit(1);
  }

  const backupsDir = path.resolve(process.cwd(), 'backups');
  if (!fs.existsSync(backupsDir)) return null;

  const targetPrefix = isProd ? 'backup_prod_' : 'backup_dev_';
  const matchingFiles = fs
    .readdirSync(backupsDir)
    .filter((f) => f.startsWith(targetPrefix) && f.endsWith('.json'))
    .map((f) => ({ name: f, time: fs.statSync(path.join(backupsDir, f)).mtimeMs }))
    .sort((a, b) => b.time - a.time);

  return matchingFiles.length > 0 ? path.join(backupsDir, matchingFiles[0].name) : null;
}

async function restoreTable(
  pool: ReturnType<typeof getDbPool>,
  tableName: string,
  rows: Record<string, unknown>[],
  isDryRun: boolean
): Promise<{ success: boolean; inserted: number; error?: string }> {
  if (rows.length === 0) {
    return { success: true, inserted: 0 };
  }

  if (isDryRun) {
    return { success: true, inserted: rows.length };
  }

  const safeTable = tableName.replace(/[^a-zA-Z0-9_]/g, '');
  let inserted = 0;

  for (const row of rows) {
    const keys = Object.keys(row);
    if (keys.length === 0) continue;

    const columns = keys.map((k) => `"${k.replace(/[^a-zA-Z0-9_]/g, '')}"`).join(', ');
    const placeholders = keys.map((_, idx) => `$${idx + 1}`).join(', ');
    const values = keys.map((k) => {
      const val = row[k];
      if (typeof val === 'object' && val !== null && !Array.isArray(val) && !(val instanceof Date)) {
        return JSON.stringify(val);
      }
      return val;
    });

    try {
      await pool.query(
        `INSERT INTO "${safeTable}" (${columns}) VALUES (${placeholders}) ON CONFLICT DO NOTHING`,
        values
      );
      inserted++;
    } catch (err: any) {
      return { success: false, inserted, error: err?.message || String(err) };
    }
  }

  return { success: true, inserted };
}

async function run(): Promise<void> {
  const backupFile = getSpecifiedOrLatestBackup();
  if (!backupFile) {
    console.error(`❌ No backup file found in backups/ directory.`);
    console.error(`Please provide one with --file <path> or run a backup first.`);
    process.exit(1);
  }

  const isDryRun = !isConfirmed;
  const pool = getDbPool();

  console.log(`============================================================`);
  console.log(`PostgreSQL Database Restore`);
  console.log(`Target:      ${isProd ? 'PRODUCTION' : 'DEVELOPMENT'}`);
  console.log(`File:        ${backupFile}`);
  console.log(`Mode:        ${isDryRun ? 'DRY-RUN (Pass --confirm to execute)' : 'LIVE RESTORE'}`);
  console.log(`============================================================\n`);

  if (isProd && !isDryRun) {
    console.log(`⚠️ ATTENTION: RESTORING TO PRODUCTION DATABASE`);
  }

  const rawJson = fs.readFileSync(backupFile, 'utf8');
  const backup = JSON.parse(rawJson) as {
    metadata: { target: string; timestamp: string };
    data: Record<string, Record<string, unknown>[]>;
  };

  const backupTables = Object.keys(backup.data || {});
  console.log(`Backup metadata: created on ${backup.metadata.timestamp} for ${backup.metadata.target}`);
  console.log(`Found ${backupTables.length} tables in backup file.\n`);

  console.log(`Computing foreign key dependency graph via information_schema...`);
  const sortedTables = await computeTopologicalOrder(pool, backupTables);
  console.log(`Resolved dependency order (${sortedTables.length} tables):\n  ${sortedTables.join(' -> ')}\n`);

  let totalRestored = 0;
  let totalErrors = 0;

  for (const table of sortedTables) {
    const rows = backup.data[table] || [];
    process.stdout.write(`Restoring ${table.padEnd(25)} (${rows.length.toString().padStart(5)} rows)... `);

    const result = await restoreTable(pool, table, rows, isDryRun);
    if (result.success) {
      console.log(`✓ ${isDryRun ? 'dry-run ok' : `${result.inserted} rows restored`}`);
      totalRestored += result.inserted;
    } else {
      console.log(`❌ ERROR: ${result.error}`);
      totalErrors++;
    }
  }

  console.log(`\n============================================================`);
  if (isDryRun) {
    console.log(`🔍 DRY-RUN COMPLETED: All ${totalRestored} rows across ${sortedTables.length} tables verified.`);
    console.log(`To actually write to the database, run:`);
    console.log(`  npx tsx src/scripts/db/restoreDatabase.ts ${isProd ? '--prod' : '--dev'} --confirm`);
  } else {
    console.log(`✅ RESTORE COMPLETED!`);
    console.log(`  Total rows restored: ${totalRestored}`);
    console.log(`  Table errors:        ${totalErrors}`);
  }
  console.log(`============================================================`);
}

run().catch((err) => {
  console.error('Fatal restore error:', err);
  process.exit(1);
});
